199	/* ---------------------------------------------------------------- */
200	/* Small helpers                                                      */
201	/* ---------------------------------------------------------------- */
202	static inline uint32_t xr_read32le(const uint8_t *b)
203	{
204		return (uint32_t)b[0] | ((uint32_t)b[1] << 8)
205				| ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
206	}
207	
208	static inline uint64_t xr_read64le(const uint8_t *b)
209	{
210		return (uint64_t)xr_read32le(b) | ((uint64_t)xr_read32le(b + 4) << 32);
211	}
212	
213	static inline void xr_write32le(uint8_t *b, uint32_t v)
214	{
215		b[0] = (uint8_t)v;
216		b[1] = (uint8_t)(v >> 8);
217		b[2] = (uint8_t)(v >> 16);
218		b[3] = (uint8_t)(v >> 24);
219	}
220	
221	static inline void xr_write64le(uint8_t *b, uint64_t v)
222	{
223		xr_write32le(b, (uint32_t)v);
224		xr_write32le(b + 4, (uint32_t)(v >> 32));
225	}
226	
227	static inline uint32_t xr_read32be(const uint8_t *b)
228	{
229		return ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16)
230				| ((uint32_t)b[2] << 8) | (uint32_t)b[3];
231	}
232	
233	static inline void xr_write32be(uint8_t *b, uint32_t v)
234	{
235		b[0] = (uint8_t)(v >> 24);
236		b[1] = (uint8_t)(v >> 16);
237		b[2] = (uint8_t)(v >> 8);
238		b[3] = (uint8_t)v;
239	}
240	
241	/* Number of bytes a VLI takes when encoded. */
242	static inline uint32_t xr_vli_size(xr_vli v)
243	{
244		uint32_t n = 0;
245		do {
246			++n;
247			v >>= 7;
248		} while (v != 0);
249		return n;
250	}
251	
252	xr_ret xr_vli_encode(xr_vli vli, size_t *vli_pos, uint8_t *out,
253			size_t *out_pos, size_t out_size);
254	xr_ret xr_vli_decode(xr_vli *vli, size_t *vli_pos, const uint8_t *in,
255			size_t *in_pos, size_t in_size);
256	
257	/* Buffer-to-buffer helper used by several coders. */
258	static inline size_t xr_bufcpy(const uint8_t *restrict in,
259			size_t *restrict in_pos, size_t in_size,
260			uint8_t *restrict out, size_t *restrict out_pos,
261			size_t out_size)
262	{
263		const size_t in_avail = in_size - *in_pos;
264		const size_t out_avail = out_size - *out_pos;
265		const size_t n = in_avail < out_avail ? in_avail : out_avail;
266		memcpy(out + *out_pos, in + *in_pos, n);
267		*in_pos += n;
268		*out_pos += n;
269		return n;
270	}
271	
272	#define xr_min(a, b) ((a) < (b) ? (a) : (b))
273	#define xr_max(a, b) ((a) > (b) ? (a) : (b))
274	
275	#endif
