1	#include "lzma_common.h"
2	#include "lz_decoder.h"
3	#include "lzma_decoder.h"
4	#include "filter.h"
5	
6	typedef enum {
7		SEQ_CONTROL,
8		SEQ_UNCOMPRESSED_1,
9		SEQ_UNCOMPRESSED_2,
10		SEQ_COMPRESSED_0,
11		SEQ_COMPRESSED_1,
12		SEQ_PROPERTIES,
13		SEQ_LZMA,
14		SEQ_COPY
15	} lzma2_sequence;
16	
17	typedef struct {
18		lzma2_sequence sequence;
19		lzma2_sequence next_sequence;
20		void *lzma;
21		uint32_t uncompressed_size;
22		uint32_t compressed_size;
23		bool need_props;
24		bool need_dictionary_reset;
25	} lzma2_dec;
26	
27	static xr_ret lzma2_decode(void *coder_ptr, xr_dict *restrict dict,
28			const uint8_t *restrict in, size_t *restrict in_pos,
29			size_t in_size, bool eof)
30	{
31		lzma2_dec *coder = coder_ptr;
32	
33		while (*in_pos < in_size || coder->sequence == SEQ_LZMA) {
34			switch (coder->sequence) {
35			case SEQ_CONTROL: {
36				const uint32_t control = in[*in_pos];
37				++*in_pos;
38	
39				if (control == 0x00)
40					return XR_STREAM_END;
41	
42				if (control >= 0x80) {
43					const uint32_t mode = (control >> 5) & 0x03;
44	
45					if (mode == 3) {
46						xr_dict_reset(dict);
47						coder->need_dictionary_reset = false;
48					} else if (coder->need_dictionary_reset) {
49						return XR_DATA_ERROR;
50					}
51	
52					if (mode >= 2) {
53						coder->need_props = false;
54						coder->next_sequence = SEQ_PROPERTIES;
55					} else if (coder->need_props) {
56						return XR_DATA_ERROR;
57					} else {
58						coder->next_sequence = SEQ_LZMA;
59						if (mode == 1)
60							xr_lzma_dec_reset_state(
61									coder->lzma);
62					}
63	
64					coder->uncompressed_size =
65							(control & 0x1F) << 16;
66					coder->sequence = SEQ_UNCOMPRESSED_1;
67				} else {
68					if (control > 0x02)
69						return XR_DATA_ERROR;
70	
71					if (control == 0x01) {
72						xr_dict_reset(dict);
73						coder->need_dictionary_reset = false;
74						coder->need_props = true;
75					} else if (coder->need_dictionary_reset) {
76						return XR_DATA_ERROR;
77					}
78	
79					coder->uncompressed_size = 0;
80					coder->next_sequence = SEQ_COPY;
81					coder->sequence = SEQ_UNCOMPRESSED_1;
82				}
83				break;
84			}
85	
86			case SEQ_UNCOMPRESSED_1:
87				coder->uncompressed_size += (uint32_t)in[(*in_pos)++]
88						<< 8;
89				coder->sequence = SEQ_UNCOMPRESSED_2;
90				break;
91	
92			case SEQ_UNCOMPRESSED_2:
93				coder->uncompressed_size += (uint32_t)in[(*in_pos)++] + 1;
94				coder->sequence = coder->next_sequence == SEQ_COPY
95						? SEQ_COPY : SEQ_COMPRESSED_0;
96				break;
97	
98			case SEQ_COMPRESSED_0:
99				coder->compressed_size = (uint32_t)in[(*in_pos)++] << 8;
100				coder->sequence = SEQ_COMPRESSED_1;
101				break;
102	
103			case SEQ_COMPRESSED_1:
104				coder->compressed_size += (uint32_t)in[(*in_pos)++] + 1;
105				xr_lzma_dec_reset_rc(coder->lzma);
106				xr_lzma_dec_set_uncompressed(coder->lzma,
107						coder->uncompressed_size, false);
108				coder->sequence = coder->next_sequence;
109				break;
110	
111			case SEQ_PROPERTIES:
112				if (!xr_lzma_dec_set_props_byte(coder->lzma,
113						in[*in_pos]))
114					return XR_DATA_ERROR;
115				++*in_pos;
116				xr_lzma_dec_reset_state(coder->lzma);
117				xr_lzma_dec_set_uncompressed(coder->lzma,
118						coder->uncompressed_size, false);
119				coder->sequence = SEQ_LZMA;
120				break;
121	
122			case SEQ_LZMA: {
123				const size_t in_start = *in_pos;
124				size_t limit = in_size;
125				bool chunk_eof = false;
126	
127				if ((uint64_t)(in_size - *in_pos)
128						>= (uint64_t)coder->compressed_size) {
129					limit = *in_pos + coder->compressed_size;
130					chunk_eof = true;
131				}
132	
133				const xr_ret ret = xr_lzma_dec_code(coder->lzma, dict,
134						in, in_pos, limit,
135						chunk_eof || eof);
136	
137				const size_t in_used = *in_pos - in_start;
138				if (in_used > coder->compressed_size)
139					return XR_DATA_ERROR;
140				coder->compressed_size -= (uint32_t)in_used;
141	
142				if (ret == XR_STREAM_END) {
143					if (coder->compressed_size != 0)
144						return XR_DATA_ERROR;
145					if (!xr_lzma_dec_rc_finished(coder->lzma))
146						return XR_DATA_ERROR;
147					coder->sequence = SEQ_CONTROL;
148					break;
149				}
150	
151				if (ret != XR_OK)
152					return ret;
153	
154				return XR_OK;
155			}
156	
157			case SEQ_COPY: {
158				size_t n = in_size - *in_pos;
159				const size_t room = dict->limit - dict->pos;
160				if (n > room)
161					n = room;
162				if (n > coder->uncompressed_size)
163					n = coder->uncompressed_size;
164	
165				if (n > 0) {
166					memcpy(dict->buf + dict->pos, in + *in_pos, n);
167					dict->pos += n;
168					if (dict->pos > dict->full)
169						dict->full = dict->pos;
170					*in_pos += n;
171					coder->uncompressed_size -= (uint32_t)n;
172				}
173	
174				if (coder->uncompressed_size == 0) {
175					/* The LZMA state must be reset after an
176					 * uncompressed chunk. */
177					xr_lzma_dec_reset_state(coder->lzma);
178					coder->sequence = SEQ_CONTROL;
179					break;
180				}
181	
182				return XR_OK;
183			}
184			}
185		}
186	
187		return XR_OK;
188	}
189	
190	static void lzma2_decoder_end(void *coder_ptr)
191	{
192		lzma2_dec *coder = coder_ptr;
193		free(coder->lzma);
194		free(coder);
195	}
196	
197	static xr_ret lzma2_decoder_init_lz(xr_lz_decoder *lz,
198			xr_lz_options *lz_options, const void *opt)
199	{
200		const xr_options_lzma *options = opt;
201	
202		if (lz->coder == NULL) {
203			lzma2_dec *coder = calloc(1, sizeof(lzma2_dec));
204			if (coder == NULL)
205				return XR_MEM_ERROR;
206			coder->lzma = malloc(xr_lzma_dec_size());
207			if (coder->lzma == NULL) {
208				free(coder);
209				return XR_MEM_ERROR;
210			}
211			lz->coder = coder;
212			lz->code = &lzma2_decode;
213			lz->end = &lzma2_decoder_end;
214			lz->reset = NULL;
215			lz->set_uncompressed = NULL;
216		}
217	
218		lzma2_dec *coder = lz->coder;
219		coder->sequence = SEQ_CONTROL;
220		coder->need_props = true;
221		coder->need_dictionary_reset = true;
222		coder->uncompressed_size = 0;
223		coder->compressed_size = 0;
224	
225		xr_lzma_dec_init(coder->lzma);
226		xr_lzma_dec_reset_state(coder->lzma);
227	
228		lz_options->dict_size = options->dict_size;
229		lz_options->preset_dict = options->preset_dict;
230		lz_options->preset_dict_size = options->preset_dict_size;
231		return XR_OK;
232	}
233	
234	xr_ret xr_lzma2_decoder_init(xr_next_coder *next, const xr_filter *filters)
235	{
236		return xr_lz_decoder_init(next, filters, &lzma2_decoder_init_lz);
237	}
238	
239	uint64_t xr_lzma2_decoder_memusage(const void *opt)
240	{
241		const xr_options_lzma *options = opt;
242		return xr_lz_decoder_memusage(options->dict_size)
243				+ xr_lzma_dec_size() + sizeof(lzma2_dec);
244	}
245	
246	xr_ret xr_lzma2_props_decode(void **options, const uint8_t *props,
247			size_t props_size)
248	{
249		if (props_size != 1)
250			return XR_OPTIONS_ERROR;
251		if (props[0] > 40)
252			return XR_OPTIONS_ERROR;
253	
254		xr_options_lzma *opt = malloc(sizeof(xr_options_lzma));
255		if (opt == NULL)
256			return XR_MEM_ERROR;
257		memset(opt, 0, sizeof(*opt));
258	
259		if (props[0] == 40) {
260			opt->dict_size = UINT32_MAX;
261		} else {
262			opt->dict_size = 2 | ((uint32_t)props[0] & 1);
263			opt->dict_size <<= props[0] / 2 + 11;
264		}
265	
266		opt->lc = XR_LC_DEFAULT;
267		opt->lp = XR_LP_DEFAULT;
268		opt->pb = XR_PB_DEFAULT;
269		*options = opt;
270		return XR_OK;
271	}
