1	/* Sliding-window dictionary used by the LZMA/LZMA2 decoders. */
2	#ifndef XZR_LZ_DECODER_H
3	#define XZR_LZ_DECODER_H
4	
5	#include "common.h"
6	
7	typedef struct {
8		uint8_t *buf;      /* Dictionary buffer */
9		size_t pos;        /* Write position */
10		size_t full;       /* How many bytes are valid in buf */
11		size_t limit;      /* Write limit for the current call */
12		size_t size;       /* Allocated size of buf */
13	} xr_dict;
14	
15	typedef struct {
16		void *coder;
17		/* `eof` tells the LZ layer that in_size is the end of all the input
18		 * that will ever be available for the current compressed unit. */
19		xr_ret (*code)(void *coder, xr_dict *restrict dict,
20				const uint8_t *restrict in, size_t *restrict in_pos,
21				size_t in_size, bool eof);
22		void (*reset)(void *coder, const void *options);
23		void (*set_uncompressed)(void *coder, xr_vli uncompressed_size,
24				bool allow_eopm);
25		void (*end)(void *coder);
26	} xr_lz_decoder;
27	
28	typedef struct {
29		size_t dict_size;
30		const uint8_t *preset_dict;
31		size_t preset_dict_size;
32	} xr_lz_options;
33	
34	static inline uint8_t xr_dict_get(const xr_dict *dict, uint32_t distance)
35	{
36		size_t offset = dict->pos - distance - 1;
37		if (distance >= dict->pos)
38			offset += dict->size;
39		return dict->full > 0 ? dict->buf[offset] : 0;
40	}
41	
42	static inline bool xr_dict_put(xr_dict *dict, uint8_t byte)
43	{
44		if (dict->pos == dict->limit)
45			return false;
46		dict->buf[dict->pos++] = byte;
47		if (dict->pos > dict->full)
48			dict->full = dict->pos;
49		return true;
50	}
51	
52	/* Copies *len bytes from `distance` back. Returns true if all were copied. */
53	static inline bool xr_dict_repeat(xr_dict *dict, uint32_t distance,
54			uint32_t *len)
55	{
56		size_t left = dict->limit - dict->pos;
57		if (left > *len)
58			left = *len;
59		*len -= (uint32_t)left;
60	
61		size_t back = dict->pos - distance - 1;
62		if (distance >= dict->pos)
63			back += dict->size;
64	
65		while (left-- > 0) {
66			dict->buf[dict->pos++] = dict->buf[back++];
67			if (back == dict->size)
68				back = 0;
69		}
70	
71		if (dict->pos > dict->full)
72			dict->full = dict->pos;
73	
74		return *len == 0;
75	}
76	
77	static inline void xr_dict_reset(xr_dict *dict)
78	{
79		dict->pos = 0;
80		dict->full = 0;
81	}
82	
83	static inline bool xr_dict_is_distance_valid(const xr_dict *dict,
84			uint32_t distance)
85	{
86		return (size_t)distance < dict->full;
87	}
88	
89	xr_ret xr_lz_decoder_init(xr_next_coder *next, const xr_filter *filters,
90			xr_ret (*lz_init)(xr_lz_decoder *lz, xr_lz_options *lz_options,
91				const void *options));
92	
93	uint64_t xr_lz_decoder_memusage(uint64_t dict_size);
94	
95	#endif
