/* Shared plumbing for the "simple" branch/call/jump (BCJ) filters.
 *
 * All BCJ filters transform whole instructions in place.  The wrapper in
 * simple_coder.c takes care of buffering a partial instruction at the end
 * of a chunk so that the result does not depend on how the data is split
 * between calls.
 */
#ifndef XZR_SIMPLE_PRIVATE_H
#define XZR_SIMPLE_PRIVATE_H

#include "common.h"
#include "filter.h"

/* A filter function converts as many complete instructions as it can from
 * buffer[0 .. size) in place and returns the number of bytes it handled.
 * The caller keeps the unhandled tail and offers it again later.
 *
 * `now_pos` is the offset of buffer[0] from the beginning of the data
 * (the low 32 bits of it, plus the start offset given in the options).
 */
typedef size_t (*xr_simple_fn)(void *simple, uint32_t now_pos,
		bool is_encoder, uint8_t *buffer, size_t size);

typedef struct {
	/* The next coder in the chain.  For an encoder the filtered data is
	 * pushed into it; for a decoder the data to un-filter is pulled from
	 * it.  code == NULL means that this filter is the last one and the
	 * data is simply copied from in[] to out[]. */
	xr_next_coder next;

	/* Filter specific function and its private state (may be NULL). */
	xr_simple_fn filter;
	void *simple;

	/* Position of the next byte to filter, counted from the start of
	 * the uncompressed data (plus options->start_offset). */
	uint32_t now_pos;

	bool is_encoder;

	/* Decoder: the next coder reported the end of the data.
	 * Encoder: everything has been handed to the next coder. */
	bool end_was_reached;

	/* Encoder: the last chunk has been prepared into buffer[]. */
	bool finishing;

	/* Encoder: XR_STREAM_END has already been returned. */
	bool finished;

	/* Temporary buffer.  buffer[0 .. filtered) holds converted bytes
	 * that still need to be delivered, starting at buffer[pos].
	 * buffer[filtered .. size) holds bytes that could not be converted
	 * yet (a partial instruction). */
	uint8_t *buffer;
	size_t allocated;
	size_t pos;
	size_t filtered;
	size_t size;
} xr_simple_coder;

/* Initialises the shared wrapper and then the rest of the filter chain.
 *
 * unfiltered_max is the largest number of bytes the filter function may
 * leave unconverted at the end of a buffer (i.e. the instruction size).
 * alignment is the required alignment of the start offset.
 */
xr_ret xr_simple_coder_init(xr_next_coder *next, const xr_filter *filters,
		xr_simple_fn filter, size_t simple_size,
		size_t unfiltered_max, uint32_t alignment, bool is_encoder);

/* Per-architecture initialisers. */
xr_ret xr_x86_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder);
xr_ret xr_powerpc_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder);
xr_ret xr_ia64_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder);
xr_ret xr_arm_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder);
xr_ret xr_armthumb_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder);
xr_ret xr_arm64_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder);
xr_ret xr_sparc_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder);
xr_ret xr_riscv_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder);

#endif

/* Streaming wrapper shared by all branch/call/jump filters. */

#include "simple_private.h"

/* Size of the temporary buffer.  Any value that is a multiple of the
 * largest instruction size (16, for IA-64) and clearly larger than it
 * gives identical output, because every BCJ filter converts complete
 * instructions only and the unconverted tail is carried over. */
#define SIMPLE_BUFFER_SIZE 4096

static size_t call_filter(xr_simple_coder *coder, uint8_t *buffer, size_t size)
{
	const size_t filtered = coder->filter(coder->simple, coder->now_pos,
			coder->is_encoder, buffer, size);
	coder->now_pos += (uint32_t)filtered;
	return filtered;
}

/* Drops the bytes that have already been delivered and moves the
 * unconverted tail to the beginning of the buffer. */
static void compact(xr_simple_coder *coder)
{
	if (coder->filtered > 0) {
		coder->size -= coder->filtered;
		memmove(coder->buffer, coder->buffer + coder->filtered,
				coder->size);
		coder->pos = 0;
		coder->filtered = 0;
	}
}

/* ---------------------------------------------------------------- */
/* Decoder: pull data from the next coder and convert it back.        */
/* ---------------------------------------------------------------- */
static xr_ret pull(xr_simple_coder *coder, const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size, xr_action action)
{
	if (coder->next.code == NULL) {
		xr_bufcpy(in, in_pos, in_size, out, out_pos, out_size);

		if (action != XR_RUN && *in_pos == in_size)
			coder->end_was_reached = true;

		return XR_OK;
	}

	const xr_ret ret = coder->next.code(coder->next.coder, in, in_pos,
			in_size, out, out_pos, out_size, action);

	if (ret == XR_STREAM_END) {
		coder->end_was_reached = true;
		return XR_OK;
	}

	return ret;
}

static xr_ret simple_decode(xr_simple_coder *coder,
		const uint8_t *restrict in, size_t *restrict in_pos,
		size_t in_size, uint8_t *restrict out,
		size_t *restrict out_pos, size_t out_size, xr_action action)
{
	while (true) {
		/* Flush the already converted bytes. */
		if (coder->pos < coder->filtered) {
			xr_bufcpy(coder->buffer, &coder->pos, coder->filtered,
					out, out_pos, out_size);

			if (coder->pos < coder->filtered)
				return XR_OK;
		}

		compact(coder);

		if (coder->end_was_reached) {
			if (coder->size == 0)
				return XR_STREAM_END;

			/* The last partial instruction is copied as is. */
			coder->filtered = coder->size;
			continue;
		}

		if (*out_pos == out_size)
			return XR_OK;

		const size_t out_avail = out_size - *out_pos;

		if (out_avail > coder->size) {
			/* There is room to work directly in out[]. */
			const size_t out_start = *out_pos;

			memcpy(out + *out_pos, coder->buffer, coder->size);
			*out_pos += coder->size;
			coder->size = 0;

			const xr_ret ret = pull(coder, in, in_pos, in_size,
					out, out_pos, out_size, action);
			if (ret != XR_OK)
				return ret;

			const size_t n = *out_pos - out_start;
			const size_t f = call_filter(coder, out + out_start, n);
			const size_t unfiltered = n - f;

			memcpy(coder->buffer, out + *out_pos - unfiltered,
					unfiltered);
			*out_pos -= unfiltered;
			coder->size = unfiltered;

			if (coder->end_was_reached)
				continue;

			return XR_OK;
		}

		/* Very little room in out[]; use the temporary buffer. */
		const xr_ret ret = pull(coder, in, in_pos, in_size,
				coder->buffer, &coder->size, coder->allocated,
				action);
		if (ret != XR_OK)
			return ret;

		coder->filtered = call_filter(coder, coder->buffer,
				coder->size);

		if (coder->filtered == 0 && !coder->end_was_reached)
			return XR_OK;
	}
}

/* ---------------------------------------------------------------- */
/* Encoder: convert the input and push it to the next coder.          */
/* ---------------------------------------------------------------- */
static xr_ret simple_encode(xr_simple_coder *coder,
		const uint8_t *restrict in, size_t *restrict in_pos,
		size_t in_size, uint8_t *restrict out,
		size_t *restrict out_pos, size_t out_size, xr_action action)
{
	if (coder->finished)
		return XR_STREAM_END;

	while (true) {
		/* Hand the converted bytes over to the next coder. */
		if (coder->pos < coder->filtered) {
			if (coder->next.code == NULL) {
				xr_bufcpy(coder->buffer, &coder->pos,
						coder->filtered,
						out, out_pos, out_size);
			} else {
				const xr_action a = coder->finishing
						? action : XR_RUN;
				const xr_ret ret = coder->next.code(
						coder->next.coder,
						coder->buffer, &coder->pos,
						coder->filtered,
						out, out_pos, out_size, a);

				if (ret == XR_STREAM_END) {
					coder->finished = true;
					return XR_STREAM_END;
				}

				if (ret != XR_OK)
					return ret;
			}

			if (coder->pos < coder->filtered)
				return XR_OK;
		}

		compact(coder);

		if (coder->finishing) {
			if (coder->next.code == NULL) {
				coder->finished = true;
				return XR_STREAM_END;
			}

			size_t dummy_pos = 0;
			const xr_ret ret = coder->next.code(coder->next.coder,
					coder->buffer, &dummy_pos, 0,
					out, out_pos, out_size, action);

			if (ret == XR_STREAM_END)
				coder->finished = true;

			return ret;
		}

		/* Take more input. */
		if (coder->size < coder->allocated && *in_pos < in_size) {
			size_t n = coder->allocated - coder->size;
			if (n > in_size - *in_pos)
				n = in_size - *in_pos;

			memcpy(coder->buffer + coder->size, in + *in_pos, n);
			*in_pos += n;
			coder->size += n;
		}

		if (coder->size == coder->allocated) {
			coder->filtered = call_filter(coder, coder->buffer,
					coder->size);

			/* The buffer is much bigger than one instruction so
			 * this cannot happen; be safe against looping. */
			if (coder->filtered == 0)
				return XR_PROG_ERROR;

			continue;
		}

		if (action == XR_RUN)
			return XR_OK;

		/* End of input: convert what can be converted, the rest is
		 * copied as is. */
		(void)call_filter(coder, coder->buffer, coder->size);
		coder->filtered = coder->size;
		coder->finishing = true;
	}
}

static xr_ret simple_code(void *coder_ptr, const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size, xr_action action)
{
	xr_simple_coder *coder = coder_ptr;

	if (coder->is_encoder)
		return simple_encode(coder, in, in_pos, in_size,
				out, out_pos, out_size, action);

	return simple_decode(coder, in, in_pos, in_size,
			out, out_pos, out_size, action);
}

static void simple_coder_end(void *coder_ptr)
{
	xr_simple_coder *coder = coder_ptr;
	xr_next_end(&coder->next);
	free(coder->simple);
	free(coder->buffer);
	free(coder);
}

xr_ret xr_simple_coder_init(xr_next_coder *next, const xr_filter *filters,
		xr_simple_fn filter, size_t simple_size,
		size_t unfiltered_max, uint32_t alignment, bool is_encoder)
{
	xr_simple_coder *coder = calloc(1, sizeof(xr_simple_coder));
	if (coder == NULL)
		return XR_MEM_ERROR;

	coder->next = XR_NEXT_CODER_INIT;
	coder->allocated = SIMPLE_BUFFER_SIZE;
	if (coder->allocated < 4 * unfiltered_max)
		coder->allocated = 4 * unfiltered_max;

	coder->buffer = malloc(coder->allocated);
	if (coder->buffer == NULL) {
		free(coder);
		return XR_MEM_ERROR;
	}

	if (simple_size > 0) {
		coder->simple = calloc(1, simple_size);
		if (coder->simple == NULL) {
			free(coder->buffer);
			free(coder);
			return XR_MEM_ERROR;
		}
	}

	coder->filter = filter;
	coder->is_encoder = is_encoder;

	if (filters[0].options != NULL) {
		const xr_options_bcj *options = filters[0].options;
		coder->now_pos = options->start_offset;

		if ((coder->now_pos & (alignment - 1)) != 0) {
			free(coder->simple);
			free(coder->buffer);
			free(coder);
			return XR_OPTIONS_ERROR;
		}
	}

	next->coder = coder;
	next->code = &simple_code;
	next->end = &simple_coder_end;
	next->id = filters[0].id;

	const xr_ret ret = xr_next_filter_init(&coder->next, filters + 1,
			is_encoder);
	if (ret != XR_OK) {
		simple_coder_end(coder);
		next->coder = NULL;
		next->code = NULL;
		next->end = NULL;
		return ret;
	}

	return XR_OK;
}

/* ---------------------------------------------------------------- */
/* Public entry points                                                */
/* ---------------------------------------------------------------- */
static xr_ret simple_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder)
{
	switch (filters[0].id) {
	case XR_FILTER_X86:
		return xr_x86_coder_init(next, filters, is_encoder);
	case XR_FILTER_POWERPC:
		return xr_powerpc_coder_init(next, filters, is_encoder);
	case XR_FILTER_IA64:
		return xr_ia64_coder_init(next, filters, is_encoder);
	case XR_FILTER_ARM:
		return xr_arm_coder_init(next, filters, is_encoder);
	case XR_FILTER_ARMTHUMB:
		return xr_armthumb_coder_init(next, filters, is_encoder);
	case XR_FILTER_ARM64:
		return xr_arm64_coder_init(next, filters, is_encoder);
	case XR_FILTER_SPARC:
		return xr_sparc_coder_init(next, filters, is_encoder);
	case XR_FILTER_RISCV:
		return xr_riscv_coder_init(next, filters, is_encoder);
	default:
		break;
	}

	return XR_PROG_ERROR;
}

xr_ret xr_simple_encoder_init(xr_next_coder *next, const xr_filter *filters)
{
	return simple_init(next, filters, true);
}

xr_ret xr_simple_decoder_init(xr_next_coder *next, const xr_filter *filters)
{
	return simple_init(next, filters, false);
}

