/* Delta filter: out[i] = in[i] - in[i - dist] (encoder) and the inverse.
 *
 * The history of the last 256 bytes is kept in the coder so that the result
 * does not depend on how the data is split between calls.
 */

#include "common.h"
#include "filter.h"

#define DELTA_DIST_MIN 1
#define DELTA_DIST_MAX 256

/* Size of the temporary buffer used when the encoder has to push the
 * converted data into the next coder. */
#define DELTA_BUFFER_SIZE 4096

typedef struct {
	xr_next_coder next;

	/* Distance between the bytes being subtracted, 1 .. 256. */
	uint32_t distance;

	/* Position in history[]; it moves backwards. */
	uint8_t pos;

	/* The most recent bytes of the unfiltered data. */
	uint8_t history[DELTA_DIST_MAX];

	/* Encoder only: converted bytes waiting to be given to next. */
	bool finishing;
	bool finished;
	size_t buf_pos;
	size_t buf_size;
	uint8_t buffer[DELTA_BUFFER_SIZE];
} delta_coder;

/* ---------------------------------------------------------------- */
/* The actual transforms                                              */
/* ---------------------------------------------------------------- */
static void delta_encode_buffer(delta_coder *coder, uint8_t *buffer,
		size_t size)
{
	const uint32_t distance = coder->distance;

	for (size_t i = 0; i < size; ++i) {
		const uint8_t tmp = coder->history[
				(distance + coder->pos) & 0xFF];
		coder->history[coder->pos-- & 0xFF] = buffer[i];
		buffer[i] = (uint8_t)(buffer[i] - tmp);
	}
}

static void delta_copy_and_encode(delta_coder *coder,
		const uint8_t *restrict in, uint8_t *restrict out, size_t size)
{
	const uint32_t distance = coder->distance;

	for (size_t i = 0; i < size; ++i) {
		const uint8_t tmp = coder->history[
				(distance + coder->pos) & 0xFF];
		coder->history[coder->pos-- & 0xFF] = in[i];
		out[i] = (uint8_t)(in[i] - tmp);
	}
}

static void delta_decode_buffer(delta_coder *coder, uint8_t *buffer,
		size_t size)
{
	const uint32_t distance = coder->distance;

	for (size_t i = 0; i < size; ++i) {
		buffer[i] = (uint8_t)(buffer[i] + coder->history[
				(distance + coder->pos) & 0xFF]);
		coder->history[coder->pos-- & 0xFF] = buffer[i];
	}
}

/* ---------------------------------------------------------------- */
/* Encoder                                                            */
/* ---------------------------------------------------------------- */
static xr_ret delta_encode(void *coder_ptr, const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size, xr_action action)
{
	delta_coder *coder = coder_ptr;

	if (coder->next.code == NULL) {
		const size_t in_avail = in_size - *in_pos;
		const size_t out_avail = out_size - *out_pos;
		const size_t size = xr_min(in_avail, out_avail);

		delta_copy_and_encode(coder, in + *in_pos, out + *out_pos,
				size);

		*in_pos += size;
		*out_pos += size;

		return action != XR_RUN && *in_pos == in_size
				? XR_STREAM_END : XR_OK;
	}

	if (coder->finished)
		return XR_STREAM_END;

	while (true) {
		if (coder->buf_pos < coder->buf_size) {
			const xr_action a = coder->finishing ? action : XR_RUN;
			const xr_ret ret = coder->next.code(coder->next.coder,
					coder->buffer, &coder->buf_pos,
					coder->buf_size,
					out, out_pos, out_size, a);

			if (ret == XR_STREAM_END) {
				coder->finished = true;
				return XR_STREAM_END;
			}

			if (ret != XR_OK)
				return ret;

			if (coder->buf_pos < coder->buf_size)
				return XR_OK;
		}

		coder->buf_pos = 0;
		coder->buf_size = 0;

		if (*in_pos == in_size) {
			if (action == XR_RUN)
				return XR_OK;

			coder->finishing = true;

			size_t dummy_pos = 0;
			const xr_ret ret = coder->next.code(coder->next.coder,
					coder->buffer, &dummy_pos, 0,
					out, out_pos, out_size, action);

			if (ret == XR_STREAM_END)
				coder->finished = true;

			return ret;
		}

		size_t n = in_size - *in_pos;
		if (n > DELTA_BUFFER_SIZE)
			n = DELTA_BUFFER_SIZE;

		delta_copy_and_encode(coder, in + *in_pos, coder->buffer, n);
		*in_pos += n;
		coder->buf_size = n;
	}
}

/* ---------------------------------------------------------------- */
/* Decoder                                                            */
/* ---------------------------------------------------------------- */
static xr_ret delta_decode(void *coder_ptr, const uint8_t *restrict in,
		size_t *restrict in_pos, size_t in_size,
		uint8_t *restrict out, size_t *restrict out_pos,
		size_t out_size, xr_action action)
{
	delta_coder *coder = coder_ptr;

	const size_t out_start = *out_pos;
	xr_ret ret;

	if (coder->next.code == NULL) {
		xr_bufcpy(in, in_pos, in_size, out, out_pos, out_size);
		ret = action != XR_RUN && *in_pos == in_size
				? XR_STREAM_END : XR_OK;
	} else {
		ret = coder->next.code(coder->next.coder, in, in_pos, in_size,
				out, out_pos, out_size, action);
	}

	delta_decode_buffer(coder, out + out_start, *out_pos - out_start);

	return ret;
}

static void delta_coder_end(void *coder_ptr)
{
	delta_coder *coder = coder_ptr;
	xr_next_end(&coder->next);
	free(coder);
}

static xr_ret delta_coder_init(xr_next_coder *next, const xr_filter *filters,
		bool is_encoder)
{
	const xr_options_delta *options = filters[0].options;

	if (options == NULL || options->dist < DELTA_DIST_MIN
			|| options->dist > DELTA_DIST_MAX)
		return XR_OPTIONS_ERROR;

	if (next->coder != NULL && next->end != NULL)
		xr_next_end(next);

	delta_coder *coder = calloc(1, sizeof(delta_coder));
	if (coder == NULL)
		return XR_MEM_ERROR;

	coder->next = XR_NEXT_CODER_INIT;
	coder->distance = options->dist;
	coder->pos = 0;

	next->coder = coder;
	next->code = is_encoder ? &delta_encode : &delta_decode;
	next->end = &delta_coder_end;
	next->id = filters[0].id;

	const xr_ret ret = xr_next_filter_init(&coder->next, filters + 1,
			is_encoder);
	if (ret != XR_OK) {
		delta_coder_end(coder);
		next->coder = NULL;
		next->code = NULL;
		next->end = NULL;
		return ret;
	}

	return XR_OK;
}

xr_ret xr_delta_encoder_init(xr_next_coder *next, const xr_filter *filters)
{
	return delta_coder_init(next, filters, true);
}

xr_ret xr_delta_decoder_init(xr_next_coder *next, const xr_filter *filters)
{
	return delta_coder_init(next, filters, false);
}

uint64_t xr_delta_coder_memusage(const void *options)
{
	const xr_options_delta *opt = options;

	if (opt == NULL || opt->dist < DELTA_DIST_MIN
			|| opt->dist > DELTA_DIST_MAX)
		return UINT64_MAX;

	return sizeof(delta_coder);
}

